using EEMS.Modules.Operations.Domain;using Microsoft.EntityFrameworkCore;namespace EEMS.Modules.Operations.Infrastructure;
#pragma warning disable CA1725
public sealed class OperationsDbContext(DbContextOptions<OperationsDbContext> options):DbContext(options){public DbSet<ReadinessState> ReadinessStates=>Set<ReadinessState>();public DbSet<IncidentState> IncidentStates=>Set<IncidentState>();public DbSet<IncidentSeverity> IncidentSeverities=>Set<IncidentSeverity>();public DbSet<ReadinessChecklist> Checklists=>Set<ReadinessChecklist>();public DbSet<ChecklistItem> ChecklistItems=>Set<ChecklistItem>();public DbSet<Incident> Incidents=>Set<Incident>();public DbSet<IncidentReview> Reviews=>Set<IncidentReview>();protected override void OnModelCreating(ModelBuilder b){b.HasDefaultSchema("operations");Config<ReadinessState>(b,"readiness_states","readiness_state_id");Config<IncidentState>(b,"incident_states","incident_state_id");Config<IncidentSeverity>(b,"incident_severities","incident_severity_id");
var c=b.Entity<ReadinessChecklist>();c.ToTable("checklists");c.HasKey(x=>x.Id);c.Property(x=>x.Id).HasColumnName("checklist_id");c.Property(x=>x.TenantId).HasColumnName("tenant_id");c.Property(x=>x.ElectionId).HasColumnName("election_id");c.Property(x=>x.ElectionCenterId).HasColumnName("election_center_id");c.Property(x=>x.StateId).HasColumnName("readiness_state_id");c.Property(x=>x.Name).HasColumnName("name").HasMaxLength(180);c.Property(x=>x.CreatedAtUtc).HasColumnName("created_at");c.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();c.HasOne<ReadinessState>().WithMany().HasForeignKey(x=>x.StateId).OnDelete(DeleteBehavior.Restrict);c.HasIndex(x=>new{x.TenantId,x.Id}).IsUnique();c.HasIndex(x=>new{x.TenantId,x.ElectionId,x.ElectionCenterId,x.Name}).IsUnique();
var i=b.Entity<ChecklistItem>();i.ToTable("checklist_items");i.HasKey(x=>x.Id);i.Property(x=>x.Id).HasColumnName("checklist_item_id");i.Property(x=>x.TenantId).HasColumnName("tenant_id");i.Property(x=>x.ChecklistId).HasColumnName("checklist_id");i.Property(x=>x.Requirement).HasColumnName("requirement").HasMaxLength(300);i.Property(x=>x.IsComplete).HasColumnName("is_complete");i.Property(x=>x.CompletedByUserId).HasColumnName("completed_by_user_id");i.Property(x=>x.CompletedAtUtc).HasColumnName("completed_at");
var n=b.Entity<Incident>();n.ToTable("incidents");n.HasKey(x=>x.Id);n.Property(x=>x.Id).HasColumnName("incident_id");n.Property(x=>x.TenantId).HasColumnName("tenant_id");n.Property(x=>x.ElectionId).HasColumnName("election_id");n.Property(x=>x.ElectionCenterId).HasColumnName("election_center_id");n.Property(x=>x.ReporterUserId).HasColumnName("reporter_user_id");n.Property(x=>x.AssignedToUserId).HasColumnName("assigned_to_user_id");n.Property(x=>x.StateId).HasColumnName("incident_state_id");n.Property(x=>x.SeverityId).HasColumnName("incident_severity_id");n.Property(x=>x.Title).HasColumnName("title").HasMaxLength(200);n.Property(x=>x.Description).HasColumnName("description").HasMaxLength(4000);n.Property(x=>x.IsConfidential).HasColumnName("is_confidential");n.Property(x=>x.ReportedAtUtc).HasColumnName("reported_at");n.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();n.HasOne<IncidentState>().WithMany().HasForeignKey(x=>x.StateId).OnDelete(DeleteBehavior.Restrict);n.HasOne<IncidentSeverity>().WithMany().HasForeignKey(x=>x.SeverityId).OnDelete(DeleteBehavior.Restrict);n.HasIndex(x=>new{x.TenantId,x.Id}).IsUnique();n.HasIndex(x=>new{x.TenantId,x.ElectionId,x.StateId,x.SeverityId});
var r=b.Entity<IncidentReview>();r.ToTable("incident_reviews");r.HasKey(x=>x.Id);r.Property(x=>x.Id).HasColumnName("incident_review_id");r.Property(x=>x.TenantId).HasColumnName("tenant_id");r.Property(x=>x.IncidentId).HasColumnName("incident_id");r.Property(x=>x.ReporterUserId).HasColumnName("reporter_user_id");r.Property(x=>x.ReviewerUserId).HasColumnName("reviewer_user_id");r.Property(x=>x.ResultingStateId).HasColumnName("resulting_state_id");r.Property(x=>x.Resolution).HasColumnName("resolution").HasMaxLength(4000);r.Property(x=>x.ReviewedAtUtc).HasColumnName("reviewed_at");r.HasOne<IncidentState>().WithMany().HasForeignKey(x=>x.ResultingStateId).OnDelete(DeleteBehavior.Restrict);}
private static void Config<T>(ModelBuilder b,string table,string key)where T:class{var e=b.Entity<T>();e.ToTable(table);e.Property<short>("Id").HasColumnName(key).ValueGeneratedNever();e.Property<string>("Code").HasColumnName("code").HasMaxLength(40);e.Property<string>("Name").HasColumnName("name").HasMaxLength(100);e.Property<bool>("IsActive").HasColumnName("is_active");e.HasIndex("Code").IsUnique();}}
